import json
import itertools

def solve_puzzle():
    # Define houses and attributes
    houses = [1, 2]  # Left to right
    Names = ['Eric', 'Arnold']
    Children = ['Bella', 'Fred']
    Lunches = ['grilled cheese', 'pizza']

    solutions = []

    # Helper to get house index (0-based) for a given value in a permutation list
    def house_of(perm, value):
        return perm.index(value)

    # Brute-force search over all permutations with constraints
    for name_perm in itertools.permutations(Names):
        for child_perm in itertools.permutations(Children):
            for lunch_perm in itertools.permutations(Lunches):

                # Constraint 1: The person who is a pizza lover is Arnold.
                if house_of(name_perm, 'Arnold') != house_of(lunch_perm, 'pizza'):
                    continue

                # Constraint 2: The person who loves eating grilled cheese is directly left of
                #               the person whose child is named Fred.
                if house_of(lunch_perm, 'grilled cheese') + 1 != house_of(child_perm, 'Fred'):
                    continue

                # If all constraints satisfied, build solution rows
                rows = []
                for i, h in enumerate(houses):
                    rows.append([
                        str(h),
                        name_perm[i],
                        child_perm[i],
                        lunch_perm[i],
                    ])
                solutions.append(rows)

    # Assuming a unique solution for well-posed Zebra puzzles
    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # If multiple solutions, choose the first but note ambiguity
        rows = solutions[0]
    else:
        rows = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Child", "Lunch"],
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), indent=2))
